{
  "case_id": "xsu_sg_010_congenital_impairment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret giver en rimelig liste over lægefaglig dokumentation, men det fremhæver ikke sygehistorikken og de seneste foreliggende lægeoplysninger. Det siger heller ikke, at de seneste oplysninger kan være ældre. Det lægger vægt på 'aktuelle følger' og 'betydning i dag' og nævner især begrænsning af arbejdsevnen. Det kan læses som et krav om ny dokumentation, hvilket rubrikken kalder en væsentlig fejl. Svaret nævner heller ikke, at en personlig redegørelse ikke ophæver det lægefaglige minimum, bortset fra at den 'ikke erstatter lægefaglige oplysninger'."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Sygehistorik som sådan nævnes ikke, kun barndomsdokumenter som bevis for, at tilstanden er medfødt. Udrednings- og behandlingsforløb nævnes ikke. Støtteforanstaltninger og skånehensyn, f.eks. afgørelser om bostøtte, mentor eller hjælpemidler, mangler helt. Personlig redegørelse nævnes, men ikke som noget, der navnlig bruges, når forholdene ikke er dokumenteret. Epikriser og journaludskrifter er med."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvilken dokumentation en ansøger med en medfødt funktionsnedsættelse kan sende med, og afviger ikke fra spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen kilde, hverken lovbestemmelse, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret fremhæver, at materialet 'så vidt muligt' skal beskrive de aktuelle følger, især begrænsningen af muligheden for at arbejde ved siden af studiet. Det betoner aktualitet på en måde, som vejledningen ikke gør for medfødte funktionsnedsættelser. Her fremhæves de seneste journalnotater, og det anerkendes, at ny dokumentation ofte mangler. Udsagnet om 'udtalelse fra egen læge' og 'undersøgelses- eller testresultater' som dokumentationsformer er ikke direkte nævnt i vejledningens afsnit 4.3, men har en vis støtte i bekendtgørelsen § 37, stk. 3, om journaler. Samlet er der en uunderbygget vægtning af aktualitet."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret mangler forbeholdet om, at de seneste foreliggende oplysninger kan være ældre, fordi medfødt funktionsnedsættelse ofte indebærer manglende nyere dokumentation. Det siger heller ikke udtrykkeligt, at eksemplerne ikke er kumulative krav, selvom 'fx' og 'kan' antyder det. Det forklarer ikke, at redegørelsen supplerer og ikke ophæver det lægefaglige minimum, bortset fra den korte bemærkning om, at den ikke erstatter lægefaglige oplysninger."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: det opregner dokumentationstyper, forklarer barndomsdokumenternes relevans, nævner aktuelle følger og redegørelsens rolle, og at SU kan bede om mere. Der er ingen indbyrdes modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret bruger 'kan', 'fx', 'kan være relevante' og 'så vidt muligt', så eksemplerne fremstår som ikke-obligatoriske. 'Vigtigt' svarer til vejledningens 'vigtigt'. Redegørelsen fremstilles ikke som en erstatning. Der er ingen absolutte krav. Bemærkningen om, at SU kan bede om mere dokumentation, svarer til § 37, stk. 5 ('kan')."
    }
  },
  "xhaile_coverage": {
    "A49": {
      "label": "partial",
      "reason": "Svaret behandler dokumentation ved medfødt funktionsnedsættelse og nævner, at barndomsdokumenter kan vise, at tilstanden er medfødt, og at en personlig beskrivelse kan supplere. Det nævner ikke sygehistorik og seneste journalnotater som det særligt vigtige. Det nævner heller ikke, at nyere dokumentation ofte mangler, og giver ikke eksempler på medfødte funktionsnedsættelser."
    },
    "A35": {
      "label": "partial",
      "reason": "Epikriser, journaler og personlig redegørelse nævnes. Svaret nævner ikke de seneste oplysninger om udrednings- og behandlingsforløb, afgørelser om bostøtte, mentor eller hjælpemidler, skånehensyn fra tidligere uddannelser eller arbejdspladser, eller at redegørelsen især bruges, når dokumentation mangler."
    }
  },
  "overall_notes": "Svaret er brugbart og forsigtigt formuleret, men det er generisk og angiver ingen kilder. Det udelader flere kritiske elementer: sygehistorik, udrednings- og behandlingsforløb, støtteforanstaltninger og skånehensyn, og at de seneste oplysninger kan være ældre. Det overbetoner 'aktuelle følger' og arbejdsbegrænsning. Derfor er C01, C02, C07 og C08 ikke opfyldt. C05 og C06 er not_assessable, fordi der ikke er angivet en kilde."
}

